import{z as i,x as l,o,c as n,q as E,j as r,D as e,d as t,s as c,S as s}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"构建系统","description":"","frontmatter":{"title":"构建系统","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/build-system.md","filePath":"cs/build-system.md","lastUpdated":1791063341000}'),B={name:"cs/build-system.md"};function p(A,a,m,h,_,u){const d=l("Mermaid");return o(),n("div",null,[a[2]||(a[2]=E('<h1 id="构建系统" tabindex="-1">构建系统 <a class="header-anchor" href="#构建系统" aria-label="Permalink to &quot;构建系统&quot;">​</a></h1><div class="epigraph"><p>构建系统记录谁依赖谁：源变了哪些目标文件过期，测试应在链接之后再跑，避免调试一份与源码脱节的镜像。</p><footer>—— 据 Kernighan &amp; Ritchie, The C Programming Language, 2nd ed.；Bryant and O&#39;Hallaron, Computer Systems: A Programmer&#39;s Perspective 整理</footer></div><p>上一课<a href="/cs/debugger-breakpoint">调试器与断点</a>需要符号与当前源对应。本课不重讲 DWARF，也不从某一种 Makefile 方言另起。缺口是：第一课的编译命令在多文件时会爆炸，头文件一改，<strong>哪些 <code>.o</code> 必须重做、哪份可执行文件是旧的</strong>。构建系统把翻译与链接收成一张依赖图。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分别编译的正确性依赖「声明改变则所有包含者重编译」。人手敲 <code>cc</code> 会漏掉边：改了 <code>foo.h</code>，只重编了 <code>foo.c</code>，<code>bar.c</code> 仍链着旧布局。缺口因此不是「一键编译」的方便，而是<strong>过期判定</strong>：边是源与头文件到目标文件、目标文件到可执行文件、可执行文件到测试。版本控制课要求旧快照可回放，构建说明必须进同一仓库。</p><p>增量构建用时间戳或内容哈希。漏边导致静默 ABI 破裂，症状像未定义行为，根子是镜像混了两代布局。多声明一次边，比事后猜「我该 clean」更接近规格。测试作为规格应成为图上的节点，而不是开发者记忆。</p><p><span class="marginnote">数字实例：100 个 <code>.c</code> 的项目全量编译 10 分钟；改 1 个头文件后，正确的增量只需重编包含它的 3 个文件加 1 次链接，约 20 秒。但漏掉 1 个该重编的 <code>.o</code>，省下的 9 分 40 秒会换成按天计的调试——症状还是「不可能」的字段值。</span></p><h3 id="构建不是「再写一层宏」" tabindex="-1">构建不是「再写一层宏」 <a class="header-anchor" href="#构建不是「再写一层宏」" aria-label="Permalink to &quot;构建不是「再写一层宏」&quot;">​</a></h3><p>预处理器在一个翻译单元内插入文本；构建系统跨文件调度进程。用递归的巨型脚本 <code>gcc *.c</code> 每次全量编译，能正确但丢掉增量，也难以表达生成代码、跨语言步骤。把构建理解成「高级 <code>#include</code>」，会把依赖方向搞反：是图调度编译器，不是文本插入整个项目。</p><p><span class="marginnote">K&amp;R 的 <code>cc</code> 命令行是单单元模型的起点。CSAPP 链接章默认你已能从多个 <code>.o</code> 做出可执行文件。Make 一类工具把「目标、依赖、配方」写成显式图；本课钉图，不背某一种语法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>节点：源、头、目标文件、库、可执行文件、测试。边：包含关系与链接关系。改叶子则沿边向上标记过期。配方必须是可重复的：同样源得到同样镜像（在工具链版本固定时）。生成文件由配方写出并被后续节点依赖，不要把生成物与手写源混成同一手改文件。</p>',12)),(o(),r(s,null,{default:e(()=>[c(d,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E5%A4%B4%E6%96%87%E4%BB%B6%22%5D%20--%3E%20C1%5B%22%E7%BC%96%E8%AF%91%E5%8D%95%E5%85%83%E4%B8%80%22%5D%0A%20%20H%20--%3E%20C2%5B%22%E7%BC%96%E8%AF%91%E5%8D%95%E5%85%83%E4%BA%8C%22%5D%0A%20%20C1%20--%3E%20O1%5B%22%E7%9B%AE%E6%A0%87%E6%96%87%E4%BB%B6%E4%B8%80%22%5D%0A%20%20C2%20--%3E%20O2%5B%22%E7%9B%AE%E6%A0%87%E6%96%87%E4%BB%B6%E4%BA%8C%22%5D%0A%20%20O1%20--%3E%20EXE%5B%22%E9%93%BE%E6%8E%A5%E5%8F%AF%E6%89%A7%E8%A1%8C%E6%96%87%E4%BB%B6%22%5D%0A%20%20O2%20--%3E%20EXE%0A%20%20EXE%20--%3E%20TEST%5B%22%E8%B7%91%E6%B5%8B%E8%AF%95%E8%A7%84%E6%A0%BC%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p>编译选项（含调试符号、优化等级）是图的一部分：选项变了，节点也过期。否则会出现「调试器里的行号对不上我以为的 <code>-O0</code>」。</p><p>清洁构建（删掉所有中间文件再做）用来验证图是否自足：若只有增量能过、清洁失败，说明有人手改了生成文件或漏了边。配方应当是声明式的输入到输出，不要在配方里偷偷改源。交叉编译把「主机上跑的测试」和「目标上跑的镜像」分成图上不同的节点，不能用同一条 <code>cc</code> 边糊弄。后课动态链接把运行时库加进这张图的「部署边」，构建成功不再等于目标机能加载。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>依赖图把模块课的「谁包含谁」从程序员脑子里搬到可执行的检查。漏边与版本历史里「只改了实现没改调用方」叠加时，最难查。构建系统不理解 C 类型，只理解文件；头文件纪律仍然必要。后课动态链接会在图上多一类节点：运行时才出现的共享库，其兼容性不能单靠这次链接时的符号解析来保证。</p><p>漏边的典型症状是：改完结构体，一部分目标文件用新偏移、一部分用旧偏移，链接成功，运行时错在「不可能」的字段值上——像 UB，其实是两代 ABI 被链进同一镜像。依赖扫描可以从 <code>#include</code> 生成边，但生成代码、汇编插入、链接脚本也是边。测试节点失败应当使整个配方失败，否则「构建成功」会掩盖规格已红。动态库作为链接输入时，构建时解析的是当时那一份 soname；运行时搜索路径可以找到另一份，这是下一课要单独画出来的边。</p><p>下图回答一个具体问题：改了 <code>foo.h</code> 之后，构建系统按什么顺序把过期沿边推到测试。</p>',6)),(o(),r(s,null,{default:e(()=>[c(d,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E7%BC%96%E8%BE%91%20foo.h%EF%BC%9A%E6%97%B6%E9%97%B4%E6%88%B3%E5%8F%98%E6%96%B0%22%5D%20--%3E%20M%5B%22%E6%B2%BF%E8%BE%B9%E6%A0%87%E8%AE%B0%20foo.o%20%E4%B8%8E%20bar.o%20%E8%BF%87%E6%9C%9F%22%5D%0A%20%20M%20--%3E%20R1%5B%22%E9%87%8D%E7%BC%96%20foo.o%22%5D%0A%20%20M%20--%3E%20R2%5B%22%E9%87%8D%E7%BC%96%20bar.o%22%5D%0A%20%20R1%20--%3E%20LK%5B%22%E9%87%8D%E9%93%BE%20app%22%5D%0A%20%20R2%20--%3E%20LK%0A%20%20LK%20--%3E%20T%5B%22%E9%87%8D%E8%B7%91%E6%B5%8B%E8%AF%95%E8%8A%82%E7%82%B9%22%5D%0A%20%20T%20--%3E%20OK%5B%22%E5%85%A8%E7%BB%BF%EF%BC%9A%E9%95%9C%E5%83%8F%E4%B8%8E%E6%BA%90%E5%90%8C%E4%BB%A3%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<p><span class="marginnote">过期判定可以想象成超市货架效期管理：原料（源/头文件）换了批次，用旧批次做出的半成品（<code>.o</code>）与成品（可执行文件）都要下架重做。构建系统的活就是自动记住「哪批原料进了哪个货架」——这件事交给人的脑子记，必漏。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不比较各种生成器，不讲分布式缓存。下一课<a href="/cs/dynamic-link-preview">动态链接直觉</a>把「链接」从构建时延到加载时。后课默认：构建是依赖图；头文件是边；测试挂在可执行文件之后；调试的镜像必须是图的产物。</p><p>配方应可在干净环境复现：依赖未声明的本机头文件，会在别人机器上静默编出另一份 ABI。把工具链版本钉在构建说明里，与源的变更集同一纪律。测试红则整图失败，不能只生成镜像。</p><p><span class="marginnote">常见误区：初学者遇到「链接成功但运行结果诡异」先怀疑编译器。更常见的根因是镜像里混了两代布局——一半 <code>.o</code> 按旧结构体偏移编译、一半按新偏移，链接器只看符号名不看布局。此时先 clean 全量重建验证图，而不是改代码碰运气。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>构建系统用依赖图决定谁过期、以何种配方重做。</li><li>头文件改变必须重编所有包含者，否则布局会静默混代。</li><li>测试与编译选项都是图上的节点。</li><li>下一课把链接从构建时推迟到程序启动。</li><li>出处：K&amp;R 的编译驱动；CSAPP 多文件链接；Make 一类工具的图模型。</li></ul>',7))])}const D=i(B,[["render",p]]);export{C as __pageData,D as default};
